import type { Reply } from '@/libs/resp';
import { NULL_ARRAY, RespError } from '@/libs/resp';

import type { Emitter, Execution, KeyEvent } from './notifications.types';

/**
 * Keyspace notifications (notify-keyspace-events), the way Redis emits them from each command.
 *
 * Redis calls notifyKeyspaceEvent() inside the command implementations; here the same events are derived after the
 * command ran, from its arguments, its reply and which keys existed before / after. Event names, classes and order
 * follow the "Events generated by different commands" table of the Redis keyspace notifications docs.
 *
 * Classes: g generic, $ string, l list, s set, h hash, z sorted set, t stream, d module (time series), x expired,
 * e evicted, n new key, m key miss.
 *
 * Written from the Redis documentation and observable behaviour; no Redis source code was consulted.
 */
export default class NotificationsEventsService {
  // ──────────────────────────────────────────────
  // Constants
  // ──────────────────────────────────────────────

  /** Event emitters by command name. */
  private static readonly EMITTERS: Record<string, Emitter> = (() => {
    const E = NotificationsEventsService;
    return {
      // ---- generic ----
      del: (x) => x.args.filter((k) => x.existedBefore(k) && !x.existsAfter(k)).map((k) => E.ev('g', 'del', k)),
      unlink: (x) => x.args.filter((k) => x.existedBefore(k) && !x.existsAfter(k)).map((k) => E.ev('g', 'del', k)),
      rename: (x) => (E.ok(x.reply) ? [E.ev('g', 'rename_from', x.args[0]), E.ev('g', 'rename_to', x.args[1])] : []),
      renamenx: (x) => (x.reply === 1 ? [E.ev('g', 'rename_from', x.args[0]), E.ev('g', 'rename_to', x.args[1])] : []),
      move: (x) => (x.reply === 1 ? [E.ev('g', 'move_from', x.args[0]), E.ev('g', 'move_to', x.args[0], Number(x.args[1]))] : []),
      copy: (x) => {
        if (x.reply !== 1) return [];
        const i = x.args.findIndex((a, j) => j >= 2 && a.toLowerCase() === 'db');
        return [E.ev('g', 'copy_to', x.args[1], i >= 0 ? Number(x.args[i + 1]) : undefined)];
      },
      restore: (x) => (E.ok(x.reply) ? [E.ev('g', 'restore', x.args[0])] : []),
      'restore-asking': (x) => (E.ok(x.reply) ? [E.ev('g', 'restore', x.args[0])] : []),
      expire: (x) => E.expireEvents(x),
      pexpire: (x) => E.expireEvents(x),
      expireat: (x) => E.expireEvents(x),
      pexpireat: (x) => E.expireEvents(x),
      persist: (x) => (x.reply === 1 ? [E.ev('g', 'persist', x.args[0])] : []),
      sort: (x) => {
        const i = x.args.findIndex((a) => a.toLowerCase() === 'store');
        if (i < 0) return [];
        const dst = x.args[i + 1];
        return x.existsAfter(dst) ? [E.ev('l', 'sortstore', dst)] : x.existedBefore(dst) ? [E.ev('g', 'del', dst)] : [];
      },

      // ---- strings ----
      set: (x) => {
        if (!E.setWrote(['set', ...x.args], x.reply, x.existedBefore(x.args[0]))) return [];
        if (!x.existsAfter(x.args[0])) return [];
        const out = [E.ev('$', 'set', x.args[0])];
        if (E.ttlOption(x.args, 2)) out.push(E.ev('g', 'expire', x.args[0]));
        return out;
      },
      setex: (x) => (E.ok(x.reply) ? [E.ev('$', 'set', x.args[0]), E.ev('g', 'expire', x.args[0])] : []),
      psetex: (x) => (E.ok(x.reply) ? [E.ev('$', 'set', x.args[0]), E.ev('g', 'expire', x.args[0])] : []),
      setnx: (x) => (x.reply === 1 ? [E.ev('$', 'set', x.args[0])] : []),
      getset: (x) => (E.ok(x.reply) || x.reply === null ? [E.ev('$', 'set', x.args[0])] : []),
      mset: (x) => x.args.filter((_, i) => i % 2 === 0).map((k) => E.ev('$', 'set', k)),
      msetnx: (x) => (x.reply === 1 ? x.args.filter((_, i) => i % 2 === 0).map((k) => E.ev('$', 'set', k)) : []),
      getdel: (x) => (E.ok(x.reply) ? [E.ev('g', 'del', x.args[0])] : []),
      getex: (x) => {
        if (!E.ok(x.reply) || x.args.length < 2) return [];
        return [E.ev('g', x.args[1].toLowerCase() === 'persist' ? 'persist' : 'expire', x.args[0])];
      },
      setrange: (x) => (x.existsAfter(x.args[0]) && x.args[2] !== '' ? [E.ev('$', 'setrange', x.args[0])] : []),
      incr: (x) => (E.ok(x.reply) ? [E.ev('$', 'incrby', x.args[0])] : []),
      // the docs: "INCR, DECR, INCRBY, DECRBY commands all generate incrby events"
      decr: (x) => (E.ok(x.reply) ? [E.ev('$', 'incrby', x.args[0])] : []),
      incrby: (x) => (E.ok(x.reply) ? [E.ev('$', 'incrby', x.args[0])] : []),
      decrby: (x) => (E.ok(x.reply) ? [E.ev('$', 'incrby', x.args[0])] : []),
      incrbyfloat: (x) => (E.ok(x.reply) ? [E.ev('$', 'incrbyfloat', x.args[0])] : []),
      append: (x) => (E.ok(x.reply) ? [E.ev('$', 'append', x.args[0])] : []),
      setbit: (x) => (E.ok(x.reply) ? [E.ev('$', 'setbit', x.args[0])] : []),
      bitop: (x) => (x.existsAfter(x.args[1]) ? [E.ev('$', 'set', x.args[1])] : x.existedBefore(x.args[1]) ? [E.ev('g', 'del', x.args[1])] : []),
      bitfield: (x) => (x.args.slice(1).some((a) => /^(set|incrby)$/i.test(a)) && x.existsAfter(x.args[0]) ? [E.ev('$', 'setbit', x.args[0])] : []),
      pfadd: (x) => (x.reply === 1 ? [E.ev('$', 'pfadd', x.args[0])] : []),
      pfmerge: (x) => (E.ok(x.reply) ? [E.ev('$', 'pfadd', x.args[0])] : []),

      // ---- lists ----
      lpush: E.same('l', 'lpush'),
      rpush: E.same('l', 'rpush'),
      lpushx: E.same('l', 'lpush'),
      rpushx: E.same('l', 'rpush'),
      lpop: E.same('l', 'lpop'),
      rpop: E.same('l', 'rpop'),
      blpop: (x) => E.popEvents(x, 'l', 'lpop'),
      brpop: (x) => E.popEvents(x, 'l', 'rpop'),
      lmpop: (x) => E.mpopEvents(x, 'l', (a) => (a.toLowerCase() === 'left' ? 'lpop' : 'rpop'), 1),
      blmpop: (x) => E.mpopEvents(x, 'l', (a) => (a.toLowerCase() === 'left' ? 'lpop' : 'rpop'), 2),
      linsert: (x) => (typeof x.reply === 'number' && x.reply > 0 ? [E.ev('l', 'linsert', x.args[0])] : []),
      lset: (x) => (E.ok(x.reply) ? [E.ev('l', 'lset', x.args[0])] : []),
      lrem: E.same('l', 'lrem'),
      ltrim: (x) => (E.ok(x.reply) && x.existedBefore(x.args[0]) ? E.withDel([E.ev('l', 'ltrim', x.args[0])], x, x.args[0]) : []),
      rpoplpush: (x) => E.moveEvents(x, 'rpop', 'lpush'),
      brpoplpush: (x) => E.moveEvents(x, 'rpop', 'lpush'),
      lmove: (x) => E.moveEvents(x, `${x.args[2].toLowerCase() === 'left' ? 'l' : 'r'}pop`, `${x.args[3].toLowerCase() === 'left' ? 'l' : 'r'}push`),
      blmove: (x) => E.moveEvents(x, `${x.args[2].toLowerCase() === 'left' ? 'l' : 'r'}pop`, `${x.args[3].toLowerCase() === 'left' ? 'l' : 'r'}push`),

      // ---- hashes ----
      hset: E.same('h', 'hset'),
      hmset: (x) => (E.ok(x.reply) ? [E.ev('h', 'hset', x.args[0])] : []),
      hsetnx: (x) => (x.reply === 1 ? [E.ev('h', 'hset', x.args[0])] : []),
      hdel: E.same('h', 'hdel'),
      hincrby: (x) => (E.ok(x.reply) ? [E.ev('h', 'hincrby', x.args[0])] : []),
      hincrbyfloat: (x) => (E.ok(x.reply) ? [E.ev('h', 'hincrbyfloat', x.args[0])] : []),

      // ---- sets ----
      sadd: E.same('s', 'sadd'),
      srem: E.same('s', 'srem'),
      spop: (x) => (E.ok(x.reply) && !(Array.isArray(x.reply) && x.reply.length === 0) ? E.withDel([E.ev('s', 'spop', x.args[0])], x, x.args[0]) : []),
      smove: (x) => (x.reply === 1 ? E.withDel([E.ev('s', 'srem', x.args[0])], x, x.args[0]).concat(E.ev('s', 'sadd', x.args[1])) : []),
      sinterstore: (x) => E.storeEvents(x, 's', 'sinterstore'),
      sunionstore: (x) => E.storeEvents(x, 's', 'sunionstore'),
      sdiffstore: (x) => E.storeEvents(x, 's', 'sdiffstore'),

      // ---- sorted sets ----
      zadd: (x) => {
        if (!E.ok(x.reply) || x.reply === 0 && !x.existsAfter(x.args[0])) return [];
        const incr = x.args.slice(1, 7).some((a) => a.toLowerCase() === 'incr');
        return [E.ev('z', incr ? 'zincr' : 'zadd', x.args[0])];
      },
      zincrby: (x) => (E.ok(x.reply) ? [E.ev('z', 'zincr', x.args[0])] : []),
      zrem: E.same('z', 'zrem'),
      zremrangebyscore: E.same('z', 'zrembyscore'),
      zremrangebyrank: E.same('z', 'zrembyrank'),
      zremrangebylex: E.same('z', 'zrembylex'),
      zpopmin: (x) => (Array.isArray(x.reply) && x.reply.length ? E.withDel([E.ev('z', 'zpopmin', x.args[0])], x, x.args[0]) : []),
      zpopmax: (x) => (Array.isArray(x.reply) && x.reply.length ? E.withDel([E.ev('z', 'zpopmax', x.args[0])], x, x.args[0]) : []),
      bzpopmin: (x) => E.popEvents(x, 'z', 'zpopmin'),
      bzpopmax: (x) => E.popEvents(x, 'z', 'zpopmax'),
      zmpop: (x) => E.mpopEvents(x, 'z', (a) => (a.toLowerCase() === 'min' ? 'zpopmin' : 'zpopmax'), 1),
      bzmpop: (x) => E.mpopEvents(x, 'z', (a) => (a.toLowerCase() === 'min' ? 'zpopmin' : 'zpopmax'), 2),
      zunionstore: (x) => E.storeEvents(x, 'z', 'zunionstore'),
      zinterstore: (x) => E.storeEvents(x, 'z', 'zinterstore'),
      zdiffstore: (x) => E.storeEvents(x, 'z', 'zdiffstore'),
      zrangestore: (x) => E.storeEvents(x, 'z', 'zrangestore'),
      geoadd: (x) => (E.ok(x.reply) && x.existsAfter(x.args[0]) ? [E.ev('z', 'zadd', x.args[0])] : []),

      // ---- streams ----
      xadd: (x) => {
        if (!E.ok(x.reply)) return [];
        const out = [E.ev('t', 'xadd', x.args[0])];
        // xtrim follows only when the trimming option really removed entries
        const key = x.args[0];
        const trimmed = x.sizeBefore && x.sizeAfter ? x.sizeAfter(key) < x.sizeBefore(key) + 1 : x.args.some((a) => /^(maxlen|minid)$/i.test(a));
        if (trimmed && x.args.some((a) => /^(maxlen|minid)$/i.test(a))) out.push(E.ev('t', 'xtrim', key));
        return out;
      },
      xdel: E.same('t', 'xdel'),
      xtrim: E.same('t', 'xtrim'),
      xsetid: (x) => (E.ok(x.reply) ? [E.ev('t', 'xsetid', x.args[0])] : []),
      xgroup: (x) => {
        const sub = (x.args[0] ?? '').toLowerCase();
        // DELCONSUMER replies the consumer's pending count, which may be 0
        if (!E.ok(x.reply) || (x.reply === 0 && sub !== 'delconsumer')) return [];
        const names: Record<string, string> = {
          create: 'xgroup-create',
          createconsumer: 'xgroup-createconsumer',
          delconsumer: 'xgroup-delconsumer',
          destroy: 'xgroup-destroy',
          setid: 'xgroup-setid',
        };
        return names[sub] ? [E.ev('t', names[sub], x.args[1])] : [];
      },

      // ---- time series (module key events, class d) ----
      'ts.create': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.create', x.args[0])] : []),
      'ts.alter': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.alter', x.args[0])] : []),
      'ts.add': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.add', x.args[0])] : []),
      'ts.incrby': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.incrby', x.args[0])] : []),
      'ts.decrby': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.decrby', x.args[0])] : []),
      'ts.del': (x) => (E.positive(x.reply) ? [E.ev('d', 'ts.del', x.args[0])] : []),
      // one ts.add per sample written (failed samples are error replies in the array)
      'ts.madd': (x) => (Array.isArray(x.reply) ? x.reply.flatMap((r, i) => (typeof r === 'number' ? [E.ev('d', 'ts.add', x.args[i * 3])] : [])) : []),
      'ts.createrule': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.createrule:src', x.args[0]), E.ev('d', 'ts.createrule:dest', x.args[1])] : []),
      'ts.deleterule': (x) => (E.ok(x.reply) ? [E.ev('d', 'ts.deleterule:src', x.args[0]), E.ev('d', 'ts.deleterule:dest', x.args[1])] : []),
    };
  })();

  // ──────────────────────────────────────────────
  // Private Helpers
  // ──────────────────────────────────────────────

  private static ev(cls: string, event: string, key: string, db?: number): KeyEvent {
    return db === undefined ? { cls, event, key } : { cls, event, key, db };
  }

  /** An emitter for commands whose positive reply means one `cls` / `event` event on their first key. */
  private static same(cls: string, event: string): Emitter {
    const E = NotificationsEventsService;
    return (x) => (E.positive(x.reply) ? E.withDel([E.ev(cls, event, x.args[0])], x, x.args[0]) : []);
  }

  private static ok(reply: Reply): boolean {
    return !(reply instanceof RespError) && reply !== null && reply !== NULL_ARRAY;
  }

  private static positive(reply: Reply): boolean {
    if (Array.isArray(reply) && reply.length === 0) return false;
    return typeof reply === 'number' ? reply > 0 : typeof reply === 'bigint' ? reply > 0n : NotificationsEventsService.ok(reply);
  }

  /** A key emptied by the command gets a generic `del` after the type event. */
  private static withDel(events: KeyEvent[], x: Execution, key: string): KeyEvent[] {
    if (x.existedBefore(key) && !x.existsAfter(key)) events.push(NotificationsEventsService.ev('g', 'del', key));
    return events;
  }

  private static ttlOption(args: string[], from: number): boolean {
    return args.slice(from).some((a) => /^(ex|px|exat|pxat)$/i.test(a));
  }

  private static expireEvents(x: Execution): KeyEvent[] {
    if (x.reply !== 1) return [];
    // A time in the past deletes the key: Redis then emits `del` instead of `expire`.
    return [NotificationsEventsService.ev('g', x.existsAfter(x.args[0]) ? 'expire' : 'del', x.args[0])];
  }

  private static popEvents(x: Execution, cls: string, event: string): KeyEvent[] {
    if (!Array.isArray(x.reply) || typeof x.reply[0] !== 'string') return [];
    const key = x.reply[0];
    return NotificationsEventsService.withDel([NotificationsEventsService.ev(cls, event, key)], x, key);
  }

  private static mpopEvents(x: Execution, cls: string, eventFor: (side: string) => string, numkeysAt: number): KeyEvent[] {
    if (!Array.isArray(x.reply) || typeof x.reply[0] !== 'string') return [];
    const n = Number(x.args[numkeysAt - 1]);
    const side = x.args[numkeysAt + n] ?? '';
    const key = x.reply[0];
    return NotificationsEventsService.withDel([NotificationsEventsService.ev(cls, eventFor(side), key)], x, key);
  }

  private static moveEvents(x: Execution, popEvent: string, pushEvent: string): KeyEvent[] {
    const E = NotificationsEventsService;
    if (!E.ok(x.reply)) return [];
    return E.withDel([E.ev('l', popEvent, x.args[0])], x, x.args[0]).concat(E.ev('l', pushEvent, x.args[1]));
  }

  private static storeEvents(x: Execution, cls: string, event: string): KeyEvent[] {
    const dst = x.args[0];
    if (x.existsAfter(dst)) return [NotificationsEventsService.ev(cls, event, dst)];
    return x.existedBefore(dst) ? [NotificationsEventsService.ev('g', 'del', dst)] : [];
  }

  // ──────────────────────────────────────────────
  // Public Methods
  // ──────────────────────────────────────────────

  /**
   * Whether SET stored its value. Without GET the reply tells (OK / null); with GET the reply is the old value, so the
   * NX / XX condition is evaluated against whether the key existed before.
   */
  static setWrote(args: readonly string[], reply: Reply, existedBefore: boolean): boolean {
    if (reply instanceof RespError) return false;
    const opts = args.slice(2).map((a) => a.toLowerCase());
    if (!opts.includes('get')) return reply !== null;
    if (opts.includes('nx')) return !existedBefore;
    if (opts.includes('xx')) return existedBefore;
    return true;
  }

  /** Events for one executed command (without the `new` / `keymiss` / `expired` / `evicted` classes, which the server adds itself). */
  static keyspaceEvents(x: Execution): KeyEvent[] {
    if (x.reply instanceof RespError) return [];
    const emit = NotificationsEventsService.EMITTERS[x.name];
    return emit ? emit(x) : [];
  }
}
